import pennywise, pickle, copy, datetime as dt
from decimal import Decimal
def t(s):
    try: print(repr(s), '->', pennywise.parse(s))
    except Exception as e: print(repr(s), '-> EXC', type(e).__name__, e, getattr(e,'line',None))
for s in ["2024-03-01\tfood\t-5\t  note  with \t inner  \t", "   2024-03-01   food   5", "  # c\n\t#x\n2024-03-01 a 1",
          "2024-03-01 a .5","2024-03-01 a 12.","2024-03-01 a +-5","2024-03-01 a --5","2024-03-01 a 5e2","2024-03-01 a NaN","2024-03-01 a Infinity",
          "2024-03-01 a 1_000","2024-03-01 a ٥","2024-03-01 a ５","٢٠٢٤-٠٣-٠١ a 1","２０２４-03-01 a 1","2024-03-01 a 1", "0000-01-01 a 1","9999-12-31 a 1","10000-01-01 a 1",
          "2024-13-01 a 1","2024-02-29 a 1","2023-02-29 a 1","2024-3-1 a 1","2024/03/01 a 1","2024-03-01a 1","2024-03-01 a","2024-03-01",
          "2024-03-01 a 1 note", "2024-03-01 a 1", " 2024-03-01 a 1", "2024-03-01 a　b 1", "2024-03-01 ÄBC 1", "2024-03-01 İ 1",
          "2024-03-01 a -0.00", "2024-03-01 a 007.10", "2024-03-01 a 1 #note", "\n\n\nbad", "2024-03-01 a 1\x00x"]:
    t(s)
e = pennywise.parse("2024-03-01 a -0.00")[0]; print(repr(e.amount), pennywise.balance([e]), pennywise.by_category([e]))
try: pennywise.parse("x")
except pennywise.ParseError as err:
    print(isinstance(err, ValueError), err.line, str(err), err.args)
    try: print(pickle.loads(pickle.dumps(err)))
    except Exception as x: print("pickle EXC", type(x).__name__, x)
    try: print(copy.copy(err))
    except Exception as x: print("copy EXC", type(x).__name__, x)
for arg in [b"2024-03-01 a 1", None, 5, ["2024-03-01 a 1"]]:
    t(arg)
E = pennywise.parse("2024-03-01 Food 1\n2024-03-05 b 2\n2024-03-10 food 3")
F = pennywise.filter_entries
print(F(E, category="FOOD"), F(E, category=""), F(E, since=dt.date(2024,3,5), until=dt.date(2024,3,5)), F(E, since=dt.date(2024,3,6), until=dt.date(2024,3,1)))
print(F(iter(E)), type(F(E)), F([], category="x"), F(E, None, None, None) == E)
for kw in [dict(since="2024-03-01"), dict(since=dt.datetime(2024,3,1)), dict(category=5), dict(category="ÄBC".upper())]:
    try: print(kw, F(E, **kw))
    except Exception as x: print(kw, "EXC", type(x).__name__, x)
print(type(pennywise.balance([])), pennywise.balance([]), pennywise.by_month([]), pennywise.by_category(iter(E)), pennywise.by_month(E))
print(pennywise.balance(iter(E)))
g = (x for x in E); print(pennywise.balance(g), pennywise.balance(g))
print(hash(E[0]), E[0] == pennywise.Entry(dt.date(2024,3,1),'food',Decimal('1')))
print(pennywise.Entry(dt.date(2024,3,1),'food',Decimal('1')).note == "")
